34	TextSearchQuery::TextSearchQuery(String function_name_, TextSearchMode search_mode_, TextIndexDirectReadMode direct_read_mode_, std::vector<String> tokens_)
35	    : function_name(std::move(function_name_))
36	    , search_mode(search_mode_)
