43	SipHash TextSearchQuery::getHash() const
44	{
45	    SipHash hash;
46	    hash.update(function_name);
47	    hash.update(search_mode);
48	    hash.update(direct_read_mode);
49	    hash.update(tokens.size());
50	
51	    for (const auto & token : tokens)
52	        hash.update(token);
53	
54	    return hash;
