57	MergeTreeIndexConditionText::MergeTreeIndexConditionText(
58	    const ActionsDAG::Node * predicate,
59	    ContextPtr context_,
60	    const Block & index_sample_block,
61	    TokenizerPtr tokenizer_,
62	    MergeTreeIndexTextPreprocessorPtr preprocessor_)
63	    : WithContext(context_)
64	    , header(index_sample_block)
65	    , tokenizer(tokenizer_)
66	    , preprocessor(preprocessor_)
67	{
68	    if (!predicate)
69	    {
70	        rpn.emplace_back(RPNElement::FUNCTION_UNKNOWN);
71	        return;
72	    }
73	
74	    const auto & settings = context_->getSettingsRef();
75	    static constexpr auto cache_policy = "SLRU";
76	    size_t max_memory_usage = std::min(settings[Setting::max_memory_usage] / 10ULL, 100ULL * 1024 * 1024);
77	
78	    /// If usage of global text index caches is disabled, create local
79	    /// one to share them between threads that read the same data parts.
80	    if (settings[Setting::use_text_index_dictionary_cache])
81	        dictionary_block_cache = context_->getTextIndexDictionaryBlockCache();
82	    else
83	        dictionary_block_cache = std::make_shared<TextIndexDictionaryBlockCache>(cache_policy, max_memory_usage, 0, 1.0);
84	
85	    if (settings[Setting::use_text_index_header_cache])
86	        header_cache = context_->getTextIndexHeaderCache();
87	    else
88	        header_cache = std::make_shared<TextIndexHeaderCache>(cache_policy, max_memory_usage, 0, 1.0);
89	
90	    if (settings[Setting::use_text_index_postings_cache])
91	        postings_cache = context_->getTextIndexPostingsCache();
92	    else
93	        postings_cache = std::make_shared<TextIndexPostingsCache>(cache_policy, max_memory_usage, 0, 1.0);
94	
95	    rpn = std::move(RPNBuilder<RPNElement>(
96	        predicate,
97	        context_,
98	        [&](const RPNBuilderTreeNode & node, RPNElement & out)
99	        {
100	            return this->traverseAtomNode(node, out);
101	        }).extractRPN());
102	
103	    NameSet all_search_tokens_set;
104	
105	    for (const auto & element : rpn)
106	    {
107	        for (const auto & search_query : element.text_search_queries)
108	        {
109	            all_search_tokens_set.insert(search_query->tokens.begin(), search_query->tokens.end());
110	            all_search_queries[search_query->getHash().get128()] = search_query;
111	        }
112	
113	        if (requiresReadingAllTokens(element))
114	            global_search_mode = TextSearchMode::Any;
115	    }
116	
117	    all_search_tokens = Names(all_search_tokens_set.begin(), all_search_tokens_set.end());
118	    std::ranges::sort(all_search_tokens); /// Technically not necessary but leads to nicer read patterns on sorted dictionary blocks
119	}
