171	/** RPN Builder build stack of reverse polish notation elements (RPNElements) required for index analysis.
172	  *
173	  * RPNBuilder client must provide RPNElement type that has following interface:
174	  *
175	  * struct RPNElementInterface
176	  * {
177	  *     enum Function
178	  *     {
179	  *         FUNCTION_UNKNOWN, /// Can take any value.
180	  *         /// Operators of the logical expression.
181	  *         FUNCTION_NOT,
182	  *         FUNCTION_AND,
183	  *         FUNCTION_OR,
184	  *         ...
185	  *     };
186	  *
187	  *   RPNElementInterface();
188	  *
189	  *   Function function = FUNCTION_UNKNOWN;
190	  *
191	  * }
192	  *
193	  * RPNBuilder take care of building stack of RPNElements with `NOT`, `AND`, `OR` types.
194	  * In addition client must provide ExtractAtomFromTreeFunction that returns true and RPNElement as output parameter,
195	  * if it can convert RPNBuilderTree node to RPNElement, false otherwise.
196	  */
197	template <typename RPNElement>
198	class RPNBuilder
199	{
200	public:
201	    using RPNElements = std::vector<RPNElement>;
202	    using ExtractAtomFromTreeFunction = std::function<bool (const RPNBuilderTreeNode & node, RPNElement & out)>;
203	
204	    explicit RPNBuilder(
205	        const ActionsDAG::Node * filter_actions_dag_node,
206	        ContextPtr query_context_,
207	        const ExtractAtomFromTreeFunction & extract_atom_from_tree_function_);
208	
209	    explicit RPNBuilder(const RPNBuilderTreeNode & node, const ExtractAtomFromTreeFunction & extract_atom_from_tree_function_);
210	    RPNElements && extractRPN() &&;
211	
212	private:
213	    void traverseTree(const RPNBuilderTreeNode & node);
214	    bool extractLogicalOperatorFromTree(const RPNBuilderFunctionTreeNode & function_node, RPNElement & out);
215	    const ExtractAtomFromTreeFunction & extract_atom_from_tree_function;
216	    RPNElements rpn_elements;
217	};
