296	bool RPNBuilderTreeNode::tryGetConstant(Field & output_value, DataTypePtr & output_type) const
297	{
298	    if (ast_node)
299	    {
300	        // Constant expr should use alias names if any
301	        String column_name = ast_node->getColumnName();
302	        const auto & block_with_constants = tree_context.getBlockWithConstants();
303	
304	        if (const auto * literal = ast_node->as<ASTLiteral>())
305	        {
306	            /// By default block_with_constants has only one column named "_dummy".
307	            /// If block contains only constants it's may not be preprocessed by
308	            //  ExpressionAnalyzer, so try to look up in the default column.
309	            if (!block_with_constants.has(column_name))
310	                column_name = "_dummy";
311	
312	            /// Simple literal
313	            output_value = literal->value;
314	            output_type = block_with_constants.getByName(column_name).type;
315	
316	            /// If constant is not Null, we can assume it's type is not Nullable as well.
317	            if (!output_value.isNull())
318	                output_type = removeNullable(output_type);
319	
320	            return true;
321	        }
322	        if (block_with_constants.has(column_name) && isColumnConst(*block_with_constants.getByName(column_name).column))
323	        {
324	            /// An expression which is dependent on constants only
325	            const auto & constant_column = block_with_constants.getByName(column_name);
326	            output_value = (*constant_column.column)[0];
327	            output_type = constant_column.type;
328	
329	            if (!output_value.isNull())
330	                output_type = removeNullable(output_type);
331	
332	            return true;
333	        }
334	    }
335	    else
336	    {
337	        const auto * node_without_alias = getNodeWithoutAlias(dag_node);
338	
339	        if (node_without_alias->column && isColumnConst(*node_without_alias->column))
340	        {
341	            output_value = (*node_without_alias->column)[0];
342	            output_type = node_without_alias->result_type;
343	
344	            if (!output_value.isNull())
345	                output_type = removeNullable(output_type);
346	
347	            return true;
348	        }
349	    }
350	
351	    return false;
352	}
