357	FutureSetPtr tryGetSetFromDAGNode(const ActionsDAG::Node * dag_node)
358	{
359	    if (!dag_node->column)
360	        return {};
361	
362	    const IColumn * column = dag_node->column.get();
363	    if (const auto * column_const = typeid_cast<const ColumnConst *>(column))
364	        column = &column_const->getDataColumn();
365	
366	    if (const auto * column_set = typeid_cast<const ColumnSet *>(column))
367	        return column_set->getData();
368	
369	    return {};
370	}
