374	FutureSetPtr RPNBuilderTreeNode::tryGetPreparedSet() const
375	{
376	    const auto & prepared_sets = getTreeContext().getPreparedSets();
377	
378	    if (ast_node && prepared_sets)
379	    {
380	        auto key = ast_node->getTreeHash(/*ignore_aliases=*/ true);
381	        const auto & sets = prepared_sets->getSetsFromTuple();
382	        auto it = sets.find(key);
383	        if (it != sets.end() && !it->second.empty())
384	            return it->second.at(0);
385	
386	        return prepared_sets->findSubquery(key);
387	    }
388	    if (dag_node)
389	    {
390	        const auto * node_without_alias = getNodeWithoutAlias(dag_node);
391	        return tryGetSetFromDAGNode(node_without_alias);
392	    }
393	
394	    return {};
395	}
396	
397	FutureSetPtr RPNBuilderTreeNode::tryGetPreparedSet(const DataTypes & data_types) const
398	{
399	    const auto & prepared_sets = getTreeContext().getPreparedSets();
400	
401	    if (prepared_sets && ast_node)
402	    {
403	        if (ast_node->as<ASTSubquery>() || ast_node->as<ASTTableIdentifier>())
404	            return prepared_sets->findSubquery(ast_node->getTreeHash(/*ignore_aliases=*/ true));
405	
406	        return prepared_sets->findTuple(ast_node->getTreeHash(/*ignore_aliases=*/ true), data_types);
407	    }
408	    if (dag_node)
409	    {
410	        const auto * node_without_alias = getNodeWithoutAlias(dag_node);
411	        return tryGetSetFromDAGNode(node_without_alias);
412	    }
413	
414	    return nullptr;
415	}
