MergeTreeIndexConditionText::matchSetElementColumn(const RPNBuilderTreeNode & node) const
{
    /// The node is the index column directly (e.g. a regular String column).
    if (header.has(node.getColumnName()))
        return SetElementMatch{SetElementMatch::Kind::Direct, std::nullopt};

    /// Otherwise try to match `m['key']` (i.e. `arrayElement(m, 'key')`) against an index
    /// defined on `mapValues(m)` or `mapKeys(m)`. `arrayElement` projects the map value type
    /// to a scalar, so we can analyze such condition as for a scalar string column.
    if (!node.isFunction())
        return std::nullopt;

    const auto function = node.toFunctionNode();
    if (function.getFunctionName() != "arrayElement" || function.getArgumentsSize() != 2)
        return std::nullopt;

    auto map_column_name = function.getArgumentAt(0).getColumnName();

    Field key_value;
    DataTypePtr key_type;
    if (!function.getArgumentAt(1).tryGetConstant(key_value, key_type))
        return std::nullopt;

    if (key_value.getType() != Field::Types::String)
        return std::nullopt;

    if (header.has(fmt::format("mapValues({})", map_column_name)))
        return SetElementMatch{SetElementMatch::Kind::MapValues, key_value.safeGet<String>()};

    if (header.has(fmt::format("mapKeys({})", map_column_name)))
        return SetElementMatch{SetElementMatch::Kind::MapKeys, key_value.safeGet<String>()};

    return std::nullopt;
}

bool MergeTreeIndexConditionText::tryPrepareSetForTextSearch(
    const RPNBuilderTreeNode & lhs,
    const RPNBuilderTreeNode & rhs,
    const String & function_name,
    RPNElement & out) const
{
    std::optional<size_t> set_key_position;
    std::optional<SetElementMatch> match;

    if (lhs.isFunction() && lhs.toFunctionNode().getFunctionName() == "tuple")
    {
        const auto function = lhs.toFunctionNode();
        auto arguments_size = function.getArgumentsSize();

        for (size_t i = 0; i < arguments_size; ++i)
        {
            if (auto argument_match = matchSetElementColumn(function.getArgumentAt(i)))
            {
                /// Text index support only one index column.
                if (set_key_position.has_value())
                    return false;

                set_key_position = i;
                match = argument_match;
            }
        }
    }
    else
    {
        if (auto lhs_match = matchSetElementColumn(lhs))
        {
            set_key_position = 0;
            match = lhs_match;
        }
    }

    if (!set_key_position.has_value())
        return false;

    auto future_set = rhs.tryGetPreparedSet();
    if (!future_set)
        return false;

    auto prepared_set = future_set->buildOrderedSetInplace(rhs.getTreeContext().getQueryContext());
    if (!prepared_set || !prepared_set->hasExplicitSetElements())
        return false;

    Columns columns = prepared_set->getSetElements();
    const auto & set_column = *columns[*set_key_position];

