790	    /// Otherwise try to match `m['key']` (i.e. `arrayElement(m, 'key')`) against an index
791	    /// defined on `mapValues(m)` or `mapKeys(m)`. `arrayElement` projects the map value type
792	    /// to a scalar, so we can analyze such condition as for a scalar string column.
793	    if (!node.isFunction())
794	        return std::nullopt;
795	
796	    const auto function = node.toFunctionNode();
797	    if (function.getFunctionName() != "arrayElement" || function.getArgumentsSize() != 2)
798	        return std::nullopt;
799	
800	    auto map_column_name = function.getArgumentAt(0).getColumnName();
801	
802	    Field key_value;
803	    DataTypePtr key_type;
804	    if (!function.getArgumentAt(1).tryGetConstant(key_value, key_type))
805	        return std::nullopt;
806	
807	    if (key_value.getType() != Field::Types::String)
808	        return std::nullopt;
809	
810	    if (header.has(fmt::format("mapValues({})", map_column_name)))
811	        return SetElementMatch{SetElementMatch::Kind::MapValues, key_value.safeGet<String>()};
812	
813	    if (header.has(fmt::format("mapKeys({})", map_column_name)))
814	        return SetElementMatch{SetElementMatch::Kind::MapKeys, key_value.safeGet<String>()};
